from pathlib import Path
import json,hashlib
root=Path(__file__).resolve().parents[1]
bank=json.loads((root/'checks/bank.json').read_text());oracles=json.loads((root/'checks/oracles.json').read_text())
reasons={
'8-205-7':'Утверждение о сокращении означает тождество на x≠7. Подстановка допустимого x=0 даёт a/(−7)=1, то есть a=−7. Обратно, при a=−7 числитель равен знаменателю, поэтому дробь действительно тождественно равна 1 на всей ОДЗ. Это проверяет необходимость и достаточность.',
'8-206-16':'ОДЗ: x≠1 и x≠−1. На ней перекрёстное умножение равносильно исходному уравнению и даёт x+1=x−1, то есть 2=0. Противоречие не зависит от x, следовательно действительных корней нет. Пустая выборка в oracle обозначает этот доказанный пустой набор, а не численный поиск.',
'8-209-1':'Арифметический квадратный корень определён ровно при неотрицательном подкоренном выражении. x−7≥0 равносильно x≥7. Конец x=7 допустим и даёт корень из нуля, все меньшие x запрещены; таким образом нижняя граница достигается.',
'8-220-2':'Параллелограмм обладает равными противоположными сторонами: проведя диагональ, получаем два равных треугольника по стороне и двум накрест лежащим углам. Поэтому CD=AB=9 независимо от длины BC и величины угла. Полнота следует из определения параллелограмма, дополнительных конфигураций с иным CD нет.',
'8-221-16':'Поскольку AB∥CD, треугольники ABC и ABD имеют одно основание AB и равные высоты, следовательно равные площади. Диагонали выпуклой трапеции пересекаются внутри; после вычитания общей площади AOB остаются соответственно BOC и AOD. Их площади равны, что даёт заданные 17 без предположения о равнобокости.',
'8-221-30':'AM — медиана, поэтому BM=MC. Продление задаёт AM=MD. В четырёхугольнике ABDC диагонали AD и BC взаимно делятся пополам в M; это признак параллелограмма. Противоположные стороны AB и DC равны. Доказательство не требует равнобедренности исходного треугольника.',
'8-224-10':'Оба вписанных угла по условию опираются именно на одну и ту же дугу AC, не на дополнительные дуги. Каждый равен половине градусной меры этой дуги. Следовательно равенство углов обязательно; известные 37° переносятся на второй угол без альтернативы 143°.',
'8-230-13':'Для каждого элементарного исхода (A∪B)∩(A∪Bᶜ)=A∪(B∩Bᶜ)=A. Это равенство множеств, поэтому вероятности равны при любых совместимости, зависимости и вероятности B. Отдельные численные предположения о B не используются.',
'8-234-7':'В исходном дереве между концами нового ребра существует ровно один простой путь. Вместе с новым ребром он образует простой цикл. Любой цикл нового графа обязан содержать новое ребро, так как дерево не имело циклов; удаление нового ребра из такого цикла оставило бы тот самый единственный старый путь. Значит цикл ровно один.',
'9-202-17':'ОДЗ x≠−3 и x≠0. Умножение на x(x+3) на ОДЗ даёт x(x+2)=(x−1)(x+3). После раскрытия скобок выходит x²+2x=x²+2x−3, то есть 0=−3. Ни допустимых, ни запрещённых кандидатов на решение не появляется; число корней ноль.',
'9-202-21':'Для любого a≠3 нуль числителя x=a допустим и является единственным корнем дроби. При a=3 этот единственный кандидат запрещён, а на всей оставшейся ОДЗ дробь тождественно равна 1. Поэтому отсутствие корней эквивалентно ровно a=3; разобраны все действительные параметры.',
'9-222-25':'Отражение относительно y=x меняет координаты местами: середина (x,y) и (y,x) лежит на y=x, соединяющий их вектор пропорционален (1,−1) и перпендикулярен оси. Поэтому образ (1,5) есть (5,1), его абсцисса 5. Это следует из определения отражения, а не из подстановки ответа.',
'9-224-25':'Если центральная симметрия сохраняет треугольник, она переставляет его три вершины и является инволюцией. Перестановка нечётного числа вершин обязана иметь неподвижную вершину, которая должна совпасть с центром симметрии. Две другие вершины тогда симметричны относительно первой и лежат с ней на одной прямой. Это противоречит невырожденности, значит центров нет.',
'9-224-29':'При центре O и коэффициенте 2 образ M задаётся OM′=2OM. Условие M′=M равносильно OM=2OM, то есть OM=0 и M=O. Сам O всегда неподвижен. Таким образом существование и единственность неподвижной точки доказаны.'
}
qs={q['id']:q for t in bank for q in t['tasks']}
out={}
for id,reason in reasons.items():
 q=qs[id];oracle=oracles[id]
 digest=hashlib.sha256(json.dumps([q['prompt'],q['solution'],oracle],ensure_ascii=False).encode()).hexdigest()
 out[id]={'hash':digest,'reason':reason}
(root/'checks/property-reviews-89.json').write_text(json.dumps(out,ensure_ascii=False,indent=2))
print('Reviewed:',len(out))
